export default "<!doctype html><html lang=\"en\"><head><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><meta name=\"theme-color\" content=\"#ffffff\"><title>RoundsAI \u00b7 Admin preview</title><style>\n:root{--ink:#1b2021;--muted:#8b9294;--line:#eceeef;--teal:#529c9e;--pale:#eff7f6}*{box-sizing:border-box}body{margin:0;background:#f2f3f4;color:var(--ink);font:14px/1.5 -apple-system,BlinkMacSystemFont,'Segoe UI',sans-serif;-webkit-font-smoothing:antialiased}button,input,textarea,select{font:inherit}button,a{touch-action:manipulation}button{cursor:pointer;color:var(--ink);border:1px solid #e5e8e8;background:#fff;border-radius:99px;min-height:44px;padding:10px 17px;font-weight:550;display:inline-flex;align-items:center;justify-content:center;gap:8px}button:hover:not(:disabled){background:#f5f7f7}button:disabled{opacity:.4;cursor:default}.primary{background:#1d2527;color:#fff;border-color:#1d2527}.primary:hover:not(:disabled){background:#354144}button:focus-visible,a:focus-visible,input:focus-visible,textarea:focus-visible,select:focus-visible,summary:focus-visible{outline:3px solid #8ac4c4;outline-offset:3px}input,textarea,select{border:1px solid #e6e9e9;border-radius:13px;background:#fafbfb;width:100%;padding:13px 14px;color:var(--ink)}textarea{resize:vertical;line-height:1.65}label{display:block;font-size:12px;color:#667174;font-weight:550;margin:17px 0 7px}h1{font-size:32px;letter-spacing:-1.25px;line-height:1.15;font-weight:650;margin:8px 0 12px}h2{font-size:18px;line-height:1.3;letter-spacing:-.4px;font-weight:600;margin:0}h3{font-size:15px;font-weight:600;margin:0}p{line-height:1.65;margin-top:0}small,.muted{color:var(--muted);line-height:1.6}small{display:block;font-size:11px}.eyebrow{font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--teal);font-weight:650}.shell{max-width:1440px;min-height:100dvh;margin:auto;background:white;padding-left:200px}.sidebar{position:fixed;left:max(0px,calc((100vw - 1440px)/2));top:0;bottom:0;width:200px;padding:30px 16px;border-right:1px solid var(--line);background:#fafcfc;display:flex;flex-direction:column;z-index:5}.brand{padding:0 8px 25px}.brand img{display:block;width:142px;height:36px;object-fit:cover}.brand small{font-size:8px;letter-spacing:2px;margin:5px 8px;color:var(--teal)}nav{display:grid;gap:7px}nav button{border:0;background:transparent;border-radius:13px;justify-content:flex-start;gap:12px;color:#9ca3a5;padding:13px 15px;text-align:left;font-size:12px}nav button.active{color:#377f81;background:#eef7f6}svg{width:19px;height:19px;fill:none;stroke:currentColor;stroke-width:1.6;stroke-linecap:round;stroke-linejoin:round;flex-shrink:0}.sidebar-foot{margin-top:auto;padding:20px 12px 0;font-size:11px;color:var(--muted)}a{color:#377f81;text-decoration:none}.topbar{height:82px;display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding:0 36px;gap:16px}.pill{display:inline-flex;font-size:10px;align-items:center;gap:6px;border:1px solid var(--line);padding:5px 10px;border-radius:99px;color:#718083;white-space:nowrap}.pill.good{background:var(--pale);color:#377f81;border-color:#dfeeed}.dot{height:5px;width:5px;border-radius:50%;background:var(--teal)}.account{display:flex;align-items:center;gap:10px;font-size:11px;color:var(--muted)}.avatar{width:34px;height:34px;border-radius:50%;display:grid;place-items:center;background:#eef5f5;color:#4d9396;font-size:10px;font-weight:650}.content{padding:32px 36px 60px}.title-row{display:flex;justify-content:space-between;align-items:center;gap:20px}.title-row p{margin-bottom:0}.banner{border:1px solid #e3eeee;border-radius:16px;padding:14px 18px;background:#f6fbfa;margin:24px 0;font-size:12px;color:#647c7d;display:flex;align-items:center;gap:12px}.banner strong{color:#377f81}.stats{display:grid;grid-template-columns:repeat(4,1fr);border:1px solid var(--line);border-radius:20px;background:white;margin:22px 0 26px}.stat{padding:20px 24px;border-right:1px solid var(--line)}.stat:last-child{border:0}.stat b{display:block;font-size:25px;font-weight:600;letter-spacing:-1px;margin:5px 0}.stat span{font-size:11px;color:var(--muted)}.grid{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:20px}.card{border:1px solid var(--line);border-radius:20px;padding:24px;background:#fff;min-width:0}.card p{font-size:12px;color:#879194}.cardhead{display:flex;justify-content:space-between;align-items:center;gap:12px;margin-bottom:18px}.cardhead small{margin-top:5px}.hero{background:var(--pale);border-color:#e3efee;padding:28px}.hero h2{font-size:24px;letter-spacing:-.7px;margin:9px 0}.hero p{color:#789191;max-width:500px}.row{display:flex;align-items:center;gap:9px;flex-wrap:wrap}.row.spaced{justify-content:space-between}.actions{margin-top:20px}.full{width:100%}.text-button{border:0;background:transparent;color:#529c9e;padding:5px 0;min-height:34px;border-radius:0;font-size:12px}.help{font-size:11px;color:var(--muted);margin-top:7px}.status{font-size:12px;color:#529c9e;min-height:18px;margin:10px 0}.error{color:#a44949}.hidden{display:none!important}.stack{display:grid;gap:16px}.profile-list{display:grid;gap:10px}.profile-row{width:100%;justify-content:space-between;border-radius:16px;padding:16px;text-align:left;gap:15px}.profile-row strong{display:block;font-size:13px}.profile-row small{font-weight:400;margin-top:4px}.profile-row .profile-icon{background:var(--pale);border-radius:12px;width:36px;height:36px;display:grid;place-items:center;color:var(--teal)}.profile-copy{flex:1}.chevron{color:#a2adaf}.tabs{display:flex;gap:7px;flex-wrap:wrap;margin-bottom:20px}.tabs button{font-size:11px;min-height:36px;padding:7px 13px}.tabs button.selected{color:#377f81;background:var(--pale);border-color:#d6e9e7}.locked{border:1px solid #e3eeee;border-radius:14px;padding:15px;font-size:11px;color:#718b8c;line-height:1.7;background:#f7fbfa;margin-top:20px}.locked strong{display:block;color:#529c9e;margin-bottom:5px}.output{white-space:pre-wrap;border:1px solid var(--line);border-radius:14px;background:#fafbfb;padding:18px;font-size:12px;line-height:1.8;min-height:190px;margin:14px 0 0;overflow-wrap:anywhere}.output.empty{display:grid;place-content:center;text-align:center;color:var(--muted)}.editor{min-height:235px}.section-title{display:flex;align-items:center;justify-content:space-between;margin:26px 0 15px}.section-title:first-child{margin-top:0}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;font-size:12px;text-align:left;white-space:nowrap}th{font-size:9px;letter-spacing:1px;color:#9aa2a4;font-weight:600;text-transform:uppercase;padding:12px}td{padding:16px 12px;border-top:1px solid var(--line)}tr[data-user]{cursor:pointer}tr[data-user]:hover{background:#fafcfc}.timeline-item{border-top:1px solid var(--line);padding:16px 0;display:flex;gap:12px}.timeline-item:first-child{border-top:0}.timeline-icon{color:var(--teal);background:var(--pale);width:30px;height:30px;border-radius:50%;display:grid;place-items:center;flex-shrink:0}.timeline-item strong{display:block;font-size:12px}.timeline-item small{margin-top:3px}.q{padding:20px 0;border-top:1px solid var(--line)}.q:first-child{border:0}.q h3{margin:12px 0}.q li{font-size:12px;margin:6px 0}.q blockquote{margin:16px 0;padding:15px;background:var(--pale);border-radius:13px;font-size:12px}.danger{color:#a44949}.history-item{border-top:1px solid var(--line);padding:18px 0}.history-item:first-child{border:0}details{margin-top:12px;font-size:12px}summary{cursor:pointer;color:#529c9e}.empty-state{text-align:center;padding:32px;color:var(--muted)}.empty-state h3{color:#667174;margin-bottom:8px}.settings-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}dialog{border:1px solid var(--line);border-radius:24px;padding:28px;max-width:760px;width:calc(100vw - 40px);max-height:88vh;color:var(--ink)}dialog::backdrop{background:#17252860;backdrop-filter:blur(3px)}.modal-top{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:18px}.icon-button{width:36px;height:36px;min-height:36px;padding:0}.dialog-detail{font-size:12px}.dialog-detail p{white-space:pre-wrap}.compare-grid{display:grid;grid-template-columns:1fr 1fr;gap:14px}.compare-grid h3{font-size:12px}.skeleton{padding:24px;color:var(--muted)}.breadcrumb{font-size:11px;color:#8b9294;margin-bottom:14px}.breadcrumb button{font-size:11px}.file-input{padding:8px}.preview-badge{position:fixed;right:22px;bottom:18px;background:#fff;border:1px solid var(--line);box-shadow:0 6px 25px #2035320a;border-radius:99px;padding:8px 14px;font-size:10px;color:#7b9595;z-index:4}.deployment-summary{padding:20px;border-radius:16px;background:#fafbfb;margin-top:18px}.search-row{display:flex;gap:12px;align-items:center;margin-bottom:18px}.search-row input{max-width:360px}.notice-small{font-size:11px;line-height:1.7;color:#879194}input[type=checkbox]{width:17px;accent-color:var(--teal)}.check-label{display:flex;gap:10px;align-items:center} .nav-divider{height:1px;background:var(--line);margin:10px 12px}\n@media(min-width:1440px){.sidebar{left:calc((100vw - 1440px)/2)}}\n@media(max-width:1050px){.stats{grid-template-columns:repeat(2,1fr)}.stat:nth-child(2){border:0}.stat:nth-child(-n+2){border-bottom:1px solid var(--line)}.grid,.compare-grid{grid-template-columns:1fr}.content{padding:26px}.topbar{padding:0 26px}.title-row{align-items:flex-start}.account .email{display:none}}\n@media(max-width:700px){.shell{padding:0}.sidebar{position:static;left:auto;width:100%;padding:15px 16px 8px;border:0;border-bottom:1px solid var(--line)}.brand{display:flex;align-items:center;justify-content:space-between;padding:0 4px 12px}.brand img{width:120px;height:30px}.brand small{margin:0}nav{display:flex;overflow-x:auto;gap:4px}nav button{white-space:nowrap;font-size:10px;padding:10px;gap:5px;min-height:42px}nav button svg{width:15px;height:15px}.sidebar-foot,.nav-divider{display:none}.topbar{height:58px;padding:0 20px}.content{padding:24px 18px 65px}.title-row{display:block}.title-row .row{margin-top:16px}h1{font-size:28px}.card{padding:19px}.stat{padding:16px}.banner{padding:13px;font-size:11px}.settings-grid{grid-template-columns:1fr;gap:0}.preview-badge{bottom:10px;right:10px}.account{font-size:10px}}\n</style></head><body><div class=\"shell\"><aside class=\"sidebar\"><div class=\"brand\"><img src=\"/roundsai-logo.png\" alt=\"RoundsAI\" width=\"142\" height=\"36\"><small>ADMIN WORKSPACE</small></div><nav id=\"nav\"></nav><div class=\"sidebar-foot\">Built by residents.<br>For residents.<br><br><a href=\"https://roundsai-five.vercel.app/\" target=\"_blank\" rel=\"noopener\">Open resident app \u2197</a></div></aside><header class=\"topbar\"><span class=\"pill good\"><span class=\"dot\"></span> Preview environment</span><div class=\"account\"><span class=\"email\" id=\"email\">Your private workspace</span><span class=\"avatar\">LR</span><a href=\"/roundsaiadmin\" id=\"adminSignOut\" target=\"_top\">Sign out</a></div></header><main class=\"content\" id=\"main\"><div class=\"skeleton\">Opening your admin workspace\u2026</div></main></div><div class=\"preview-badge\">Draft controls \u00b7 Resident app unchanged</div><dialog id=\"modal\"></dialog><script src=\"/roundsaiadmin/session.js\"></script><script>\ndocument.addEventListener(\"click\",e=>{if(e.target.closest(\"#adminSignOut\")){e.preventDefault();RoundsAdminSession.signOut()}});\nconst $=s=>document.querySelector(s),esc=s=>String(s??'').replace(/[&<>\"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;',\"'\":'&#39;'}[c]));\nconst paths={home:'<path d=\"m3 10 9-7 9 7v10h-6v-7H9v7H3Z\"/>',ai:'<path d=\"m12 3 2.4 6.6L21 12l-6.6 2.4L12 21l-2.4-6.6L3 12l6.6-2.4Z\"/>',notes:'<path d=\"M14 2H5v20h14V7ZM14 2v6h5M8 12h8m-8 4h8\"/>',test:'<path d=\"M9 3h6m-5 0v6L4 19a1 1 0 0 0 1 2h14a1 1 0 0 0 1-2L14 9V3M7 15h10\"/>',users:'<circle cx=\"9\" cy=\"7\" r=\"4\"/><path d=\"M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2m20 0v-2a4 4 0 0 0-3-4M15 3a4 4 0 0 1 0 8\"/>',questions:'<path d=\"M12 5v16M3 3h4a5 5 0 0 1 5 3 5 5 0 0 1 5-3h4v16h-4a5 5 0 0 0-5 2 5 5 0 0 0-5-2H3Z\"/>',history:'<path d=\"M3 11a9 9 0 1 1 2 7M3 3v8h8m1-4v5l3 2\"/>',arrow:'<path d=\"m9 5 7 7-7 7\"/>',check:'<path d=\"m5 12 4 4L19 6\"/>',close:'<path d=\"m6 6 12 12M6 18 18 6\"/>'};const icon=k=>'<svg viewBox=\"0 0 24 24\" aria-hidden=\"true\">'+(paths[k]||paths.notes)+'</svg>';\nlet profiles=[],questions=[],events=[],guardrails='',statusData={},view='home',type='progress',filter='pending',dirty=false,busy=false,sampleUsers=false,questionEdit=null;let realUsers=[],reportDates=null,trackingStart=null,userRange='7',userFrom='',userTo='',usersLoaded=false,usersLoading=false,usersError='',liveSettings=[],liveReleases=[],userRequestSerial=0;\nconst notes=['hpi','progress','consult','admission','icu','discharge'],modules=['summary','presentation','headsup','learning'];\nconst sampleActivity=[{id:'sample-1',name:'Demo Resident A',email:'resident-a@example.invalid',role:'Resident',last:'Illustrative session',charts:4,notes:6,questions:10,errors:0},{id:'sample-2',name:'Demo Resident B',email:'resident-b@example.invalid',role:'Resident',last:'Illustrative session',charts:2,notes:3,questions:7,errors:1}];\nfunction current(){return profiles.find(p=>p.type===type)}\nfunction dt(s){return new Date(s).toLocaleString('en-US',{timeZone:'America/New_York',timeZoneName:'short'})}\nasync function api(path,body){return RoundsAdminSession.api(path,body)}\nfunction message(text,error=false){const el=$('#status');if(el){el.textContent=text;el.classList.toggle('error',error)}}\nasync function run(fn){if(busy)return;busy=true;document.querySelectorAll('button').forEach(b=>b.disabled=true);try{await fn()}catch(e){message(e.message,true);const er=$('#modalError');if(er)er.textContent=e.message}finally{busy=false;document.querySelectorAll('button').forEach(b=>b.disabled=false)}}\nfunction modal(title,body){$('#modal').innerHTML='<div class=\"modal-top\"><h2>'+esc(title)+'</h2><button class=\"icon-button\" id=\"closeModal\" aria-label=\"Close dialog\">'+icon('close')+'</button></div>'+body;$('#modal').showModal()}\nfunction banner(){if(statusData.appConnected)return '<div class=\"banner\">'+icon('check')+'<div><strong>Connected to your resident app.</strong> Draft edits stay private until you explicitly publish a saved version. Question reviews update the shared live question bank.</div></div>';return '<div class=\"banner\">'+icon('check')+'<div><strong>Your preview workspace.</strong> Save, test and restore configurations here. These settings do not change the resident app.</div></div>'}\nfunction heading(kicker,title,description,actions=''){return '<div class=\"title-row\"><div><div class=\"eyebrow\">'+kicker+'</div><h1>'+title+'</h1><p class=\"muted\">'+description+'</p></div><div class=\"row\">'+actions+'</div></div>'}\nfunction stat(label,value,sub){return '<div class=\"stat\"><span>'+label+'</span><b>'+value+'</b><span>'+sub+'</span></div>'}\nfunction profileRow(p){return '<button class=\"profile-row\" data-open-profile=\"'+p.type+'\"><span class=\"profile-icon\">'+icon(notes.includes(p.type)?'notes':'ai')+'</span><span class=\"profile-copy\"><strong>'+esc(p.name)+'</strong><small>'+(p.activeVersion?'Preview version saved':'Ready to customize')+'</small></span><span class=\"chevron\">'+icon('arrow')+'</span></button>'}\nfunction render(){const nav=[['home','Overview'],['notes','Note templates'],['ai','AI instructions'],['test','Test workspace'],['users','Users & activity'],['questions','Question review'],['history','Versions & release']];$('#nav').innerHTML=nav.map(([k,label])=>'<button data-view=\"'+k+'\" class=\"'+(view===k?'active':'')+'\">'+icon(k)+'<span>'+label+'</span></button>').join('');let html='';if(view==='home')html=home();if(view==='notes'||view==='ai')html=config();if(view==='test')html=testScreen();if(view==='users')html=usersScreen();if(view==='questions')html=questionsScreen();if(view==='history')html=historyScreen();$('#main').innerHTML=html;document.title='RoundsAI \u00b7 '+nav.find(x=>x[0]===view)?.[1];if(view==='notes'||view==='ai')fillEditor();}\nfunction home(){const versions=profiles.reduce((n,p)=>n+p.versions.length,0);return heading('YOUR ADMIN WORKSPACE','A clearer view. More control.','Shape the experience behind better rounds.','<button data-view=\"test\">'+icon('test')+' Test a configuration</button>')+banner()+'<div class=\"stats\">'+stat('NOTE TEMPLATES',notes.length,'Tailor each clinical workflow')+stat('AI WORKFLOWS',modules.length,'Source-grounded instructions')+stat('PENDING QUESTIONS',questions.filter(q=>q.status==='pending').length,(statusData.appConnected?'In the live question bank':'In this preview queue'))+stat('SAVED VERSIONS',versions,'Restore an earlier configuration')+'</div><div class=\"grid\"><section class=\"card hero\"><div class=\"eyebrow\">START WITH YOUR NOTES</div><h2>Your clinical style,<br>made consistent.</h2><p>Guide the structure, detail and language of every draft. Keep the facts grounded in the chart.</p><button class=\"primary\" data-open-profile=\"progress\">Configure progress notes '+icon('arrow')+'</button></section><section class=\"card\"><div class=\"cardhead\"><div><h2>Connection status</h2><small>A transparent view of what is ready.</small></div><span class=\"pill\">'+(statusData.appConnected?'Live admin':'Preview')+'</span></div><div class=\"timeline-item\"><span class=\"timeline-icon\">'+icon('check')+'</span><div><strong>Configuration saving</strong><small>Connected \u00b7 private admin storage</small></div></div><div class=\"timeline-item\"><span class=\"timeline-icon\">'+icon('test')+'</span><div><strong>AI generation</strong><small>'+(statusData.aiConfigured?'Provider connected \u00b7 fictional samples only':'Provider key required \u00b7 instruction inspection available')+'</small></div></div><div class=\"timeline-item\"><span class=\"timeline-icon\">'+icon('users')+'</span><div><strong>Resident app & user activity</strong><small>'+(statusData.appConnected?'Connected \u00b7 real user activity':'Not connected \u00b7 awaits your approval')+'</small></div></div></section><section class=\"card\"><div class=\"cardhead\"><div><h2>Note templates</h2><small>Keep each note appropriate to its purpose.</small></div></div><div class=\"profile-list\">'+notes.slice(0,3).map(t=>profileRow(profiles.find(p=>p.type===t))).join('')+'</div><button class=\"text-button\" data-view=\"notes\">View all six templates '+icon('arrow')+'</button></section><section class=\"card\"><div class=\"cardhead\"><div><h2>Recent admin activity</h2><small>Recorded configuration and review actions.</small></div><button class=\"text-button\" data-view=\"users\">View activity</button></div>'+eventList(events.slice(0,4))+'</section></div><div class=\"status\" id=\"status\"></div>'}\nfunction config(){const isNote=view==='notes',list=isNote?notes:modules;if(!list.includes(type))type=list[0];const p=current();return heading(isNote?'CLINICAL DOCUMENTATION':'AI WORKFLOW CONTROLS',isNote?'Notes that sound like you.':'Give the AI clear direction.',isNote?'Set the structure. Preserve the detail. Keep your clinical voice.':'Choose what each workflow should emphasize and how it should respond.')+banner()+'<div class=\"tabs\">'+list.map(t=>'<button data-type=\"'+t+'\" class=\"'+(type===t?'selected':'')+'\">'+esc(profiles.find(p=>p.type===t).name)+'</button>').join('')+'</div><div class=\"grid\"><section class=\"card\"><div class=\"cardhead\"><div><h2>'+esc(p.name)+'</h2><small>Draft edits stay private until explicitly published.</small></div><span id=\"dirtyBadge\" class=\"pill\">Saved draft</span></div><label for=\"instructions\">Instructions for the AI</label><textarea id=\"instructions\" class=\"editor\" maxlength=\"24000\"></textarea><div class=\"settings-grid\"><div><label for=\"detail\">Preferred detail level</label><select id=\"detail\"><option value=\"concise\">Concise</option><option value=\"balanced\">Balanced</option><option value=\"comprehensive\">Comprehensive</option></select></div><div><label for=\"sections\">Required sections / order</label><input id=\"sections\" maxlength=\"4000\" placeholder=\"HPI \u2192 findings \u2192 assessment & plan\"></div></div><label for=\"emphasis\">What matters most?</label><textarea id=\"emphasis\" rows=\"3\" maxlength=\"4000\" placeholder=\"E.g. interval changes, respiratory support, reason for consultation\"></textarea><label for=\"avoid\">What should it avoid?</label><textarea id=\"avoid\" rows=\"2\" maxlength=\"4000\" placeholder=\"E.g. generic filler, repeated history, unsupported stability statements\"></textarea><div class=\"row actions\"><button class=\"primary\" id=\"save\">Save draft '+icon('check')+'</button><button id=\"saveVersion\">Save a version</button><button class=\"text-button\" id=\"discard\">Discard edits</button></div><div class=\"status\" id=\"status\" role=\"status\"></div></section><div class=\"stack\"><section class=\"card\"><div class=\"cardhead\"><div><h2>Your reference example</h2><small>Teach the writing style, without copying patient facts.</small></div><span class=\"pill\">Optional</span></div><label for=\"example\">Preferred example \u00b7 fictional details only</label><textarea id=\"example\" rows=\"9\" maxlength=\"12000\" placeholder=\"Paste an example that captures your clinical style\u2026\"></textarea><label for=\"importExample\">Import a text or Markdown example</label><input id=\"importExample\" type=\"file\" accept=\".txt,.md,text/plain,text/markdown\" class=\"file-input\"><small class=\"help\">The example is saved only when you choose Save draft. Use fictional or appropriately de-identified material.</small></section><section class=\"card\"><h2>Test before release</h2><p style=\"margin-top:12px\">Try the draft against the same fictional chart and inspect the exact instructions the model receives.</p><button class=\"full\" id=\"testCurrent\">'+icon('test')+' Open test workspace</button><div class=\"locked\"><strong>Always-on documentation rules</strong>Use only supplied findings and clinician plans. Preserve negation, uncertainty, numbers and chronology. A style example never supplies patient facts. These rules stay active regardless of your custom instructions.</div></section></div></div>'}\nfunction fillEditor(){const p=current(),s=p.settings||{};$('#instructions').value=p.draft;$('#example').value=p.example;for(const k of ['detail','sections','emphasis','avoid'])$('#'+k).value=s[k]||(k==='detail'?'balanced':'');dirty=false}\nfunction readEditor(){return {instructions:$('#instructions').value,example:$('#example').value,settings:Object.fromEntries(['detail','sections','emphasis','avoid'].map(k=>[k,$('#'+k).value]))}}\nfunction combined(p){const s=p.settings||{};return p.draft+'\\n\\nDETAIL LEVEL: '+(s.detail||'balanced')+(s.sections?'\\nSECTION ORDER: '+s.sections:'')+(s.emphasis?'\\nEMPHASIZE: '+s.emphasis:'')+(s.avoid?'\\nAVOID: '+s.avoid:'')}\nasync function saveProfile(version=false){let p=current(),d=await api('profile',{type,revision:p.revision,action:'save',...readEditor()});profiles=profiles.map(x=>x.type===type?d.profile:x);if(version){p=current();d=await api('profile',{type,revision:p.revision,action:'activate'});profiles=profiles.map(x=>x.type===type?d.profile:x)}dirty=false;await loadEvents();render();message(version?'Version saved. Publish it when you want new generations to use it.':'Draft saved to your private admin workspace. Live settings are unchanged.')}\nconst sample='FICTIONAL TEACHING CASE \u2014 Alex Morgan, 67-year-old man with hypertension and type 2 diabetes, admitted with pneumonia and a new oxygen requirement. Today he reports improved breathing and cough. Denies chest pain. On 2 L/min nasal cannula; oxygen saturation 95%, respiratory rate 18, BP 126/74. Examination documents right basilar crackles. Admission WBC 14.1, today 11.8; creatinine 0.9 mg/dL. Documented plan: review antimicrobial course and pending microbiology with the treating team; reassess oxygen requirement. No additional plans supplied.';\nfunction testScreen(){return heading('TEST BEFORE YOU RELEASE','A safe place to fine-tune.','Use the same fictional chart to examine your saved versions and draft instructions.')+banner()+'<div class=\"grid\"><section class=\"card\"><div class=\"cardhead\"><div><h2>Test configuration</h2><small>Nothing here changes a patient chart.</small></div><span class=\"pill\">Sandbox</span></div><label for=\"testType\">Workflow / note type</label><select id=\"testType\">'+profiles.map(p=>'<option value=\"'+p.type+'\" '+(p.type===type?'selected':'')+'>'+esc(p.name)+'</option>').join('')+'</select><label for=\"chart\">Fictional source information</label><textarea id=\"chart\" rows=\"10\" maxlength=\"15000\" placeholder=\"Paste a fictional chart or workflow input\u2026\"></textarea><button class=\"text-button\" id=\"sample\">Use Alex Morgan example</button><div class=\"row actions\"><button class=\"primary\" id=\"preview\">'+icon('ai')+' Generate AI draft</button><button id=\"inspect\">Inspect instructions</button></div><small class=\"help\">'+(statusData.aiConfigured?'AI provider connected. Generated output still requires clinician review.':'AI generation requires a provider connection. Instruction inspection works now and does not simulate an AI note.')+'</small><div class=\"status\" id=\"status\" role=\"status\"></div><div class=\"locked\"><strong>What this test uses</strong>Your saved draft and reference example. Unsaved editor changes must be saved first. Source information is not saved to the admin database.</div></section><section class=\"card\"><div class=\"cardhead\"><div><h2>Preview output</h2><small id=\"outputLabel\">Your test result will appear here.</small></div><button class=\"text-button\" id=\"copyOutput\">Copy</button></div><div class=\"output empty\" id=\"output\">Choose a workflow and add a fictional case.<br>Then inspect instructions or generate an AI draft.</div><div class=\"row actions\"><button id=\"compare\">Compare saved version & draft</button><button class=\"text-button\" id=\"editFromTest\">Edit this configuration</button></div><small class=\"help\">Comparison shows instruction differences. It is not a clinical-quality score or an AI-generated result.</small></section></div>'}\nfunction eventLabel(e){const labels={'profile.save':'Saved a draft','profile.activate':'Saved a version','profile.restore':'Restored a version to draft','question.create':'Added a question','question.edit':'Edited a question','question.approve':'Approved a question','question.reject':'Rejected a question','question.reopen':'Reopened a question','ai.preview':'Generated a test draft','release.publish':'Published settings to the app','release.rollback':'Restored a live configuration'};return labels[e.action]||e.action}\nfunction eventList(list){return list.length?list.map(e=>'<div class=\"timeline-item\"><span class=\"timeline-icon\">'+icon('history')+'</span><div><strong>'+esc(eventLabel(e))+'</strong><small>'+esc(e.target)+' \u00b7 '+esc(dt(e.at))+'</small><small>'+esc(e.by)+'</small></div></div>').join(''):'<div class=\"empty-state\"><h3>No admin actions yet</h3><small>Save your first draft to start the activity trail.</small></div>'}\nfunction usersScreen(){return heading('PEOPLE & PRODUCT ACTIVITY','See how the workspace is used.','Understand adoption, errors and learning activity without opening patient notes.','<button id=\"toggleSampleUsers\">'+(sampleUsers?'Hide sample users':'Explore sample user view')+'</button>')+banner()+'<div class=\"grid\"><section class=\"card\"><div class=\"cardhead\"><div><h2>Resident activity connection</h2><small>Production telemetry is not connected in this preview.</small></div><span class=\"pill\">Not connected</span></div><p>Once connected, this view can show each user\u2019s last activity, chart updates, generated notes, completed learning and errors.</p><div class=\"locked\"><strong>Patient records stay separate</strong>This overview uses event metadata and counts. It does not grant access to another user\u2019s charts or note contents.</div></section><section class=\"card\"><h2>Preview activity</h2><div class=\"stats\" style=\"grid-template-columns:1fr 1fr;margin-bottom:0\">'+stat('ADMIN ACTIONS',events.length,'Recent preview events')+stat('CONFIGURATIONS',profiles.filter(p=>p.revision>0).length,'With saved changes')+'</div></section></div>'+(sampleUsers?'<section class=\"card\" style=\"margin-top:20px\"><div class=\"cardhead\"><div><h2>Example user overview</h2><small>Illustrative sample accounts and counts. Not real usage data.</small></div><span class=\"pill\">Sample data</span></div><div class=\"search-row\"><input id=\"userSearch\" placeholder=\"Search sample user\" aria-label=\"Search sample users\"></div><div class=\"table-wrap\"><table><thead><tr><th>User</th><th>Role</th><th>Charts</th><th>Notes</th><th>Questions</th><th>Errors</th><th></th></tr></thead><tbody id=\"userRows\">'+userRows(sampleActivity)+'</tbody></table></div></section>':'')+'<section class=\"card\" style=\"margin-top:20px\"><div class=\"cardhead\"><div><h2>Admin audit trail</h2><small>Real actions recorded in this private preview.</small></div><button id=\"refreshActivity\">Refresh</button></div>'+eventList(events)+'<div class=\"status\" id=\"status\"></div></section>'}\nfunction userRows(list){return list.map(u=>'<tr data-user=\"'+u.id+'\"><td><strong>'+u.name+'</strong><small>'+u.email+'</small></td><td>'+u.role+'</td><td>'+u.charts+'</td><td>'+u.notes+'</td><td>'+u.questions+'</td><td>'+u.errors+'</td><td>'+icon('arrow')+'</td></tr>').join('')}\nfunction questionsScreen(){const list=questions.filter(q=>filter==='all'||q.status===filter);return heading('CLINICIAN REVIEW','Useful learning starts with good questions.','Check clinical relevance, answer accuracy and source support before approval.','<button class=\"primary\" id=\"addQuestion\">Add a question '+icon('arrow')+'</button>')+banner()+'<section class=\"card\"><div class=\"cardhead\"><div><h2>'+(statusData.appConnected?'Resident question bank':'Preview question queue')+'</h2><small>'+(statusData.appConnected?'These questions are shared with the resident app. Approval makes a question available to learners.':'This queue is separate from the resident app\u2019s question bank.')+'</small></div><span class=\"pill\">'+questions.length+' questions</span></div><div class=\"tabs\">'+['pending','approved','rejected','all'].map(f=>'<button data-filter=\"'+f+'\" class=\"'+(filter===f?'selected':'')+'\">'+f[0].toUpperCase()+f.slice(1)+'</button>').join('')+'</div>'+(list.length?list.map(q=>'<article class=\"q\"><span class=\"pill '+(q.status==='approved'?'good':'')+'\">'+esc(q.status)+'</span><h3>'+esc(q.stem)+'</h3><ol type=\"A\">'+q.options.map((o,i)=>'<li>'+esc(o)+(i===q.answer?' <strong>\u2713 Correct answer</strong>':'')+'</li>').join('')+'</ol><blockquote>'+esc(q.explanation)+'</blockquote><small>Source: '+esc(q.source)+'</small><div class=\"row actions\"><button data-edit-question=\"'+q.id+'\">Edit question</button>'+(q.status==='pending'?'<button class=\"primary\" data-review=\"approve\" data-id=\"'+q.id+'\">'+(statusData.appConnected?'Approve for learners':'Approve in preview')+'</button><button class=\"danger\" data-review=\"reject\" data-id=\"'+q.id+'\">Reject</button>':'<button data-review=\"reopen\" data-id=\"'+q.id+'\">Reopen review</button>')+'</div><details><summary>Review history</summary>'+q.history.map(e=>'<small>'+esc(e.action)+' \u00b7 '+esc(e.by)+' \u00b7 '+esc(dt(e.at))+(e.comment?' \u00b7 '+esc(e.comment):'')+'</small>').join('')+'</details></article>').join(''):'<div class=\"empty-state\"><h3>No '+(filter==='all'?'':filter+' ')+'questions yet</h3><p>Add a fictional question to try editing and approval.</p></div>')+'<div class=\"status\" id=\"status\"></div></section>'}\nfunction questionForm(q){questionEdit=q?.id||null;modal(q?'Edit question':'Add a question','<form id=\"questionForm\"><label for=\"questionTopic\">Clinical topic</label><input id=\"questionTopic\" required maxlength=\"180\" value=\"'+esc(q?.topic||'')+'\" placeholder=\"E.g. Pneumonia\"><label for=\"stem\">Clinical vignette and question</label><textarea id=\"stem\" rows=\"5\" required maxlength=\"8000\">'+esc(q?.stem||'')+'</textarea><div class=\"settings-grid\">'+[0,1,2,3].map(i=>'<div><label for=\"option'+i+'\">Choice '+'ABCD'[i]+'</label><input id=\"option'+i+'\" required maxlength=\"2000\" value=\"'+esc(q?.options[i]||'')+'\"></div>').join('')+'</div><label for=\"answer\">Correct answer</label><select id=\"answer\">'+[0,1,2,3].map(i=>'<option value=\"'+i+'\" '+(q?.answer===i?'selected':'')+'>'+'ABCD'[i]+'</option>').join('')+'</select><label for=\"explanation\">Explanation and clinical pearl</label><textarea id=\"explanation\" required rows=\"4\">'+esc(q?.explanation||'')+'</textarea><label for=\"source\">Guideline / source and version</label><input id=\"source\" required value=\"'+esc(q?.source||'')+'\" placeholder=\"Organization, guideline title, year and source URL\"><p class=\"status error\" id=\"modalError\"></p><button type=\"submit\" class=\"primary full\">Save for review</button><small class=\"help\">Editing an approved question returns it to pending review.</small></form>')}\nfunction historyScreen(){const versions=profiles.flatMap(p=>p.versions.map(v=>({...v,type:p.type,name:p.name}))).sort((a,b)=>b.at.localeCompare(a.at));return heading('VERSION HISTORY & RELEASE','Every change has a way back.','Review saved configurations and restore a previous version to the draft editor.','<button id=\"export\">Export configuration</button>')+banner()+'<div class=\"grid\"><section class=\"card\"><div class=\"cardhead\"><div><h2>Saved versions</h2><small>Restoring a version updates the preview draft only.</small></div><span class=\"pill\">'+versions.length+' versions</span></div>'+(versions.length?versions.map(v=>'<div class=\"history-item\"><div class=\"row spaced\"><div><strong>'+esc(v.name)+'</strong><small>'+esc(dt(v.at))+' \u00b7 '+esc(v.by)+'</small></div><button data-restore=\"'+v.id+'\" data-type=\"'+v.type+'\">Restore draft</button></div><details><summary>View instructions</summary><div class=\"output\">'+esc(v.instructions)+'</div></details></div>').join(''):'<div class=\"empty-state\"><h3>Your history starts here</h3><p>Save a version from a configuration editor.</p></div>')+'</section><div class=\"stack\"><section class=\"card hero\"><div class=\"eyebrow\">RELEASE CONTROL</div><h2>You decide when it goes live.</h2><p>Review the configuration bundle and export it for approval. Nothing is pushed into the resident app.</p><button class=\"primary\" id=\"reviewRelease\">Review preview release '+icon('arrow')+'</button><div class=\"deployment-summary\"><small>Resident app connection</small><strong>'+(statusData.appConnected?'Connected to resident app':'Awaiting your approval')+'</strong><small style=\"margin-top:8px\">Live releases and rollback are available below when the app connection is active.</small></div></section><section class=\"card\"><h2>Import a configuration</h2><p style=\"margin-top:12px\">Import a previously exported bundle as drafts. No live configuration is overwritten.</p><label for=\"importConfig\">Configuration JSON</label><input type=\"file\" id=\"importConfig\" accept=\".json,application/json\" class=\"file-input\"><small class=\"help\">Imports are validated before saving. Existing preview versions remain available.</small></section></div></div><div class=\"status\" id=\"status\" role=\"status\"></div>'}\nfunction navigate(v){if(dirty&&!confirm('Discard unsaved edits? Save your draft first if you want to keep them.'))return;dirty=false;view=v;render();window.scrollTo({top:0})}\nasync function loadEvents(){events=(await api('activity')).events}\nasync function restore(t,id){const p=profiles.find(p=>p.type===t);const d=await api('profile',{type:t,revision:p.revision,action:'restore',version:id});profiles=profiles.map(x=>x.type===t?d.profile:x);type=t;view=notes.includes(t)?'notes':'ai';await loadEvents();render();message('Version restored to the draft editor. Resident app unchanged.')}\nfunction inspect(){const p=current();$('#output').classList.remove('empty');$('#output').textContent='ALWAYS-ON RULES\\n'+guardrails+'\\n\\nWORKFLOW INSTRUCTIONS\\n'+combined(p)+'\\n\\nSTYLE EXAMPLE (style only)\\n'+(p.example||'(none)');$('#outputLabel').textContent='Instruction inspection \u00b7 no AI note generated';message('Showing the exact saved draft instructions.')}\nasync function generate(){const chart=$('#chart').value.trim();if(!chart)throw Error('Add a fictional case before generating a draft.');message('Generating a source-grounded draft\u2026');const p=current(),d=await api('preview',{type,instructions:combined(p),example:p.example,chart});$('#output').textContent=d.note;$('#output').classList.remove('empty');$('#outputLabel').textContent='AI draft \u00b7 verify against the supplied source';await loadEvents();message('Test draft generated. Source information was not retained.')}\nfunction exportConfig(){const blob=new Blob([JSON.stringify({version:2,environment:'admin-preview',exportedAt:new Date().toISOString(),guardrails,profiles},null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='roundsai-admin-configuration.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}\ndocument.addEventListener('input',e=>{if(['instructions','example','detail','sections','emphasis','avoid'].includes(e.target.id)){dirty=true;$('#dirtyBadge').textContent='Unsaved changes';message('Unsaved changes')}if(e.target.id==='userSearch')$('#userRows').innerHTML=userRows(sampleActivity.filter(u=>(u.name+' '+u.email).toLowerCase().includes(e.target.value.toLowerCase())))});\ndocument.addEventListener('change',e=>{if(e.target.id==='detail'){dirty=true;$('#dirtyBadge').textContent='Unsaved changes'}if(e.target.id==='testType')type=e.target.value;if(e.target.id==='importExample')run(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>48000)throw Error('Use an example under 48 KB.');const text=await f.text();if(text.length>12000)throw Error('Examples may contain up to 12,000 characters.');$('#example').value=text;dirty=true;$('#dirtyBadge').textContent='Unsaved changes';message('Example loaded. Save draft to keep it.')});if(e.target.id==='importConfig')run(async()=>{const f=e.target.files[0];if(!f)return;if(f.size>500000)throw Error('Configuration file is too large.');let x;try{x=JSON.parse(await f.text())}catch{throw Error('Select a valid JSON configuration.')}if(!Array.isArray(x.profiles)||!x.profiles.length)throw Error('No profiles found in this file.');if(x.profiles.some(p=>!profiles.some(y=>y.type===p.type)||typeof p.draft!=='string'||p.draft.length<20||p.draft.length>12000||typeof(p.example||'')!=='string'||(p.example||'').length>12000))throw Error('The file contains an invalid profile. No profiles were imported.');if(new Set(x.profiles.map(p=>p.type)).size!==x.profiles.length)throw Error('The file contains duplicate profile types.');modal('Import as preview drafts?','<p>'+x.profiles.length+' configurations will update their preview drafts. Saved versions remain available.</p><p class=\"status error\" id=\"modalError\"></p><button class=\"primary full\" id=\"confirmImport\">Import drafts</button>');$('#confirmImport').onclick=()=>run(async()=>{let done=0;for(const p of x.profiles){try{const cur=profiles.find(y=>y.type===p.type),d=await api('profile',{type:p.type,revision:cur.revision,action:'save',instructions:p.draft,example:p.example||'',settings:p.settings||{}});profiles=profiles.map(y=>y.type===p.type?d.profile:y);done++}catch(e){throw Error(done+' profiles imported before an error: '+e.message)}}$('#modal').close();await loadEvents();render();message(done+' profiles imported as preview drafts.')})})});\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view)return navigate(b.dataset.view);if(b.dataset.openProfile){if(dirty&&!confirm('Discard unsaved edits?'))return;type=b.dataset.openProfile;view=notes.includes(type)?'notes':'ai';render();window.scrollTo({top:0});return}if(b.dataset.type&&!b.dataset.restore){if(dirty&&!confirm('Discard unsaved edits?'))return;type=b.dataset.type;render();return}if(b.dataset.restore){modal('Restore saved version?','<p>This restores the saved settings into the preview draft. The resident app stays unchanged.</p><p class=\"status error\" id=\"modalError\"></p><button class=\"primary full\" id=\"confirmRestore\">Restore draft</button>');$('#confirmRestore').onclick=()=>run(async()=>{await restore(b.dataset.type,b.dataset.restore);$('#modal').close()});return}if(b.dataset.filter){filter=b.dataset.filter;render();return}if(b.dataset.editQuestion)return questionForm(questions.find(q=>q.id===b.dataset.editQuestion));if(b.dataset.review){const q=questions.find(q=>q.id===b.dataset.id),action=b.dataset.review;modal(action==='approve'?'Approve question?':action==='reject'?'Reject question?':'Reopen review?','<p>Review the question, answer and cited source before approving. '+(statusData.appConnected?'This updates the resident question bank.':'This action affects the preview queue only.')+'</p><label for=\"comment\">Review comment</label><textarea id=\"comment\" rows=\"3\" maxlength=\"2000\"></textarea><p class=\"status error\" id=\"modalError\"></p><button id=\"confirmReview\" class=\"primary full\">Confirm '+action+'</button>');$('#confirmReview').onclick=()=>run(async()=>{const d=await api('question',{action,id:q.id,revision:q.revision,comment:$('#comment').value});questions=questions.map(x=>x.id===q.id?d.question:x);await loadEvents();$('#modal').close();render();message('Question review saved.')});return}if(b.closest('[data-user]'))return;switch(b.id){case'closeModal':$('#modal').close();break;case'save':run(()=>saveProfile());break;case'saveVersion':run(()=>saveProfile(true));break;case'discard':fillEditor();$('#dirtyBadge').textContent='Saved draft';message('Editor reset to the saved draft.');break;case'testCurrent':if(dirty){message('Save your draft before opening the test workspace.',true);return}view='test';render();break;case'sample':$('#chart').value=sample;break;case'inspect':inspect();break;case'preview':run(generate);break;case'editFromTest':view=notes.includes(type)?'notes':'ai';render();break;case'compare':{const p=current(),v=p.versions.find(v=>v.id===p.activeVersion)||p.versions[0];modal('Saved version vs current draft','<div class=\"compare-grid\"><section><h3>Latest saved version</h3><div class=\"output\">'+esc(v?v.instructions:'No saved version yet. Save a version in the configuration editor first.')+'</div></section><section><h3>Current saved draft</h3><div class=\"output\">'+esc(combined(p))+'</div></section></div><small class=\"help\">Instruction comparison only. Patient data is not involved.</small>');break}case'copyOutput':run(async()=>{await navigator.clipboard.writeText($('#output').textContent);message('Output copied.')});break;case'toggleSampleUsers':sampleUsers=!sampleUsers;render();break;case'refreshActivity':run(async()=>{await loadEvents();render();message('Activity refreshed.')});break;case'addQuestion':questionForm();break;case'export':exportConfig();break;case'reviewRelease':modal('Preview release summary','<span class=\"pill good\">Configuration bundle</span><div class=\"deployment-summary\"><strong>'+profiles.filter(p=>p.revision>0).length+' customized configurations</strong><small>'+profiles.reduce((n,p)=>n+p.versions.length,0)+' saved versions \u00b7 '+questions.filter(q=>q.status==='approved').length+' questions approved in preview</small></div><p style=\"margin-top:18px\">Export this bundle for review. Use Publish saved version in each configuration editor to apply that version to new generations.</p><button id=\"export\" class=\"primary full\">Export for approval</button><small class=\"help\">This does not deploy settings or modify the resident app.</small>');break}});\ndocument.addEventListener('click',e=>{const row=e.target.closest('tr[data-user]');if(!row)return;if(statusData.appConnected){showLiveUser(row.dataset.user);return}const u=sampleActivity.find(u=>u.id===row.dataset.user);modal('Example user activity','<span class=\"pill\">Illustrative sample data</span><h3 style=\"margin-top:15px\">'+u.name+'</h3><p class=\"muted\">'+u.email+'</p><div class=\"stats\" style=\"grid-template-columns:1fr 1fr\">'+stat('CHART UPDATES',u.charts,'Illustrative count')+stat('NOTES GENERATED',u.notes,'Illustrative count')+stat('QUESTIONS ANSWERED',u.questions,'Illustrative count')+stat('ERRORS',u.errors,'Illustrative count')+'</div><p class=\"notice-small\">The connected version will populate this view from real activity events. Chart and note contents are not displayed or exposed here.</p>')});\ndocument.addEventListener('submit',e=>{if(e.target.id!=='questionForm')return;e.preventDefault();run(async()=>{const q=questions.find(x=>x.id===questionEdit),d=await api('question',{action:q?'edit':'create',topic:$('#questionTopic').value,...(q?{id:q.id,revision:q.revision}:{}),stem:$('#stem').value,options:[0,1,2,3].map(i=>$('#option'+i).value),answer:Number($('#answer').value),explanation:$('#explanation').value,source:$('#source').value});questions=q?questions.map(x=>x.id===q.id?d.question:x):[d.question,...questions];filter='pending';await loadEvents();$('#modal').close();render();message('Question saved for clinician review.')})});\nwindow.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});\nfunction dateControls(){return '<div class=\"row\" style=\"gap:12px;margin:20px 0\"><div><label for=\"dateRange\" style=\"margin-top:0\">Reporting period</label><select id=\"dateRange\"><option value=\"1\">Today</option><option value=\"7\">Last 7 days</option><option value=\"30\">Last 30 days</option><option value=\"90\">Last 90 days</option><option value=\"all\">All time</option><option value=\"custom\">Custom dates</option></select></div><div id=\"customDates\" class=\"row '+(userRange==='custom'?'':'hidden')+'\"><div><label for=\"rangeFrom\">Start date</label><input type=\"date\" id=\"rangeFrom\" value=\"'+esc(userFrom)+'\"></div><div><label for=\"rangeTo\">End date</label><input type=\"date\" id=\"rangeTo\" value=\"'+esc(userTo)+'\"></div><button id=\"applyDateRange\" style=\"align-self:end\">Apply dates</button></div><small style=\"align-self:end;margin-bottom:12px\">Eastern Time \u00b7 start and end dates included</small></div>'}\nasync function loadUsers(){const serial=++userRequestSerial;usersLoading=true;usersError='';try{const q=new URLSearchParams({range:userRange,...(userRange==='custom'?{from:userFrom,to:userTo}:{})});const d=await api('users?'+q);if(serial!==userRequestSerial)return;realUsers=d.users;reportDates=d.dates;trackingStart=d.trackingStartedAt;usersLoaded=true}catch(e){if(serial===userRequestSerial){usersError=e.message;usersLoaded=true}}finally{if(serial===userRequestSerial){usersLoading=false;if(view==='users')render()}}}\nfunction liveUserRows(list){return list.map(u=>'<tr data-user=\"'+esc(u.id)+'\" tabindex=\"0\" role=\"button\" aria-label=\"View activity for '+esc(u.email)+'\"><td><strong>'+esc(u.email)+'</strong> '+(u.is_admin?'<span class=\"pill good\">'+(u.is_owner?'Owner':'Admin')+'</span>':'')+'<small>Joined '+esc(dt(u.joined_at))+'</small></td><td>'+u.attempts+'</td><td>'+u.distinct_questions+'</td><td>'+(u.attempts?Math.round(100*u.correct/u.attempts)+'%':'\u2014')+'</td><td>'+u.notes+'</td><td>'+u.chart_drafts+'</td><td>'+u.errors+'</td><td>'+icon('arrow')+'</td></tr>').join('')}\nconst previewUsersScreen=usersScreen;\nusersScreen=function(){if(!statusData.appConnected)return previewUsersScreen();const totals=realUsers.reduce((x,u)=>({attempts:x.attempts+u.attempts,correct:x.correct+u.correct,notes:x.notes+u.notes,active:x.active+(u.attempts||u.notes||u.chart_drafts?1:0)}),{attempts:0,correct:0,notes:0,active:0});return heading('LIVE USER ANALYTICS','See the progress behind the rounds.','Real question activity, with the date range you choose.','<button id=\"refreshUsers\">Refresh data</button>')+dateControls()+(reportDates?'<p class=\"notice-small\">'+esc(reportDates.from)+' through '+esc(reportDates.to)+' \u00b7 '+esc(reportDates.timeZone)+'</p>':'')+'<div class=\"stats\">'+stat('ANSWERS SUBMITTED',totals.attempts,'Includes repeat attempts')+stat('ACCURACY',totals.attempts?Math.round(100*totals.correct/totals.attempts)+'%':'\u2014','Across recorded answers')+stat('ACTIVE USERS',totals.active,'Question or generation activity')+stat('NOTES GENERATED',totals.notes,'Since generation tracking began')+'</div><section class=\"card\"><div class=\"cardhead\"><div><h2>User activity</h2><small>Question counts cover the selected dates. Users with zero activity remain visible.</small></div><span class=\"pill good\">'+realUsers.length+' accounts</span></div><div class=\"search-row\"><input id=\"liveUserSearch\" placeholder=\"Search by email\" aria-label=\"Search real users\"></div>'+(usersLoading?'<p class=\"status\">Loading activity\u2026</p>':'')+(usersError?'<p class=\"status error\">'+esc(usersError)+'</p>':'')+'<div class=\"table-wrap\"><table><thead><tr><th>User</th><th>Answers</th><th>Unique questions</th><th>Accuracy</th><th>Notes</th><th>Chart drafts</th><th>AI errors</th><th></th></tr></thead><tbody id=\"liveUserRows\">'+liveUserRows(realUsers)+'</tbody></table></div><div class=\"locked\"><strong>What the counts mean</strong>Answers include repeat attempts; unique questions count each question once per user in this period. A zero is a recorded count, not an estimate. Note, chart-draft and AI-error metrics are available only after generation tracking was connected; older question history is included. No patient charts or note contents are exposed.</div></section><section class=\"card\" style=\"margin-top:20px\"><div class=\"cardhead\"><div><h2>Admin audit trail</h2><small>Configuration and review actions.</small></div><button id=\"refreshActivity\">Refresh</button></div>'+eventList(events)+'<div id=\"status\" class=\"status\"></div></section>'};\nfunction showLiveUser(id){const u=realUsers.find(u=>u.id===id);if(!u)return;modal('User learning activity','<span class=\"pill good\">'+esc(reportDates?.label||'Selected dates')+'</span><h3 style=\"margin-top:15px\">'+esc(u.email)+'</h3><p><label><input type=\"checkbox\" role=\"switch\" id=\"userAdminToggle\" data-user-id=\"'+esc(u.id)+'\" '+(u.is_admin?'checked ':'')+(u.is_owner||u.email===statusData.email?'disabled ':'')+'> Admin access</label><small>Full access to AI templates, publishing, user analytics and account administration.</small></p><p class=\"notice-small\">'+esc(reportDates?.from||'')+' through '+esc(reportDates?.to||'')+' \u00b7 Eastern Time</p><div class=\"stats\" style=\"grid-template-columns:1fr 1fr\">'+stat('ANSWERS',u.attempts,'Includes repeat attempts')+stat('UNIQUE QUESTIONS',u.distinct_questions,'Distinct question IDs')+stat('CORRECT',u.correct,'In selected dates')+stat('ACCURACY',u.attempts?Math.round(100*u.correct/u.attempts)+'%':'\u2014','In selected dates')+'</div><p class=\"notice-small\">Last answer in period: '+(u.last_answer_at?esc(dt(u.last_answer_at)):'None')+'<br>Last account sign-in (all time): '+(u.last_sign_in_at?esc(dt(u.last_sign_in_at)):'Not recorded')+'</p><h3>Daily breakdown</h3>'+(u.daily.length?'<div class=\"table-wrap\"><table><thead><tr><th>Date \u00b7 ET</th><th>Answers</th><th>Correct</th></tr></thead><tbody>'+u.daily.map(d=>'<tr><td>'+esc(d.date)+'</td><td>'+d.attempts+'</td><td>'+d.correct+'</td></tr>').join('')+'</tbody></table></div>':'<p class=\"muted\">No recorded answers in this period.</p>')+'<small class=\"help\">Counts are based on completed answer submissions, not opened questions.</small>')}\nconst originalRender=render;\nrender=function(){originalRender();if(view==='users'&&statusData.appConnected){$('#dateRange').value=userRange;if(!usersLoaded&&!usersLoading)queueMicrotask(loadUsers)}if(statusData.appConnected){$('.preview-badge').textContent='Live admin \u00b7 Drafts require explicit publishing';$('.topbar .pill').innerHTML='<span class=\"dot\"></span> Live admin';if(['notes','ai'].includes(view)){const p=current(),live=liveSettings.find(x=>x.workflow===type);const button=document.createElement('button');button.id='publishLive';button.textContent='Publish saved version to app';button.disabled=!p.activeVersion;$('#saveVersion').after(button);const text=document.createElement('small');text.className='help';text.textContent=live?'Live revision '+live.revision+' \u00b7 last published '+dt(live.updated_at):'No custom settings published. Resident app uses its existing defaults.';$('#status').before(text)}if(view==='history'){const section=document.createElement('section');section.className='card';section.style.marginTop='20px';section.innerHTML='<div class=\"cardhead\"><div><h2>Production release history</h2><small>Rollback publishes the selected earlier configuration as a new audited release.</small></div><span class=\"pill good\">Live app</span></div>'+(liveReleases.length?liveReleases.map(r=>'<div class=\"history-item\"><div class=\"row spaced\"><div><strong>'+esc(profiles.find(p=>p.type===r.workflow)?.name||r.workflow)+'</strong><small>'+esc(dt(r.created_at))+' \u00b7 '+esc(r.actor)+'</small></div><button data-rollback-live=\"'+r.id+'\" data-workflow=\"'+r.workflow+'\">Restore to live</button></div></div>').join(''):'<p class=\"muted\">No custom settings published yet. The resident app is using its existing defaults.</p>');$('#main').append(section)}}};\nasync function refreshLive(){const d=await api('live-settings');liveSettings=d.settings;liveReleases=d.releases}\nfunction publishDialog(){if(dirty){message('Save your edits and a version before publishing.',true);return}const p=current(),v=p.versions.find(v=>v.id===p.activeVersion),live=liveSettings.find(s=>s.workflow===type);if(!v){message('Save a version first.',true);return}modal('Publish this version to the live app?','<h3>'+esc(p.name)+'</h3><p style=\"margin-top:12px\">New generations will use this saved version. Existing patient notes and manual edits will not be rewritten.</p><div class=\"output\">'+esc(v.instructions)+'</div><p id=\"modalError\" class=\"status error\"></p><button id=\"confirmPublishLive\" class=\"primary full\">Publish saved version</button>');$('#confirmPublishLive').onclick=()=>run(async()=>{await api('profile',{type,revision:p.revision,action:'publish',expected:live?.revision||0});await refreshLive();await loadEvents();$('#modal').close();render();message('Published. New generations use this version. Existing notes are preserved.')})}\ndocument.addEventListener('change',e=>{if(e.target.id==='dateRange'){userRange=e.target.value;$('#customDates').classList.toggle('hidden',userRange!=='custom');if(userRange==='custom'){userFrom=userFrom||reportDates?.from||'';userTo=userTo||reportDates?.to||'';$('#rangeFrom').value=userFrom;$('#rangeTo').value=userTo}if(userRange!=='custom'){usersLoaded=false;loadUsers()}}});\ndocument.addEventListener('input',e=>{if(e.target.id==='liveUserSearch')$('#liveUserRows').innerHTML=liveUserRows(realUsers.filter(u=>(u.email||'').toLowerCase().includes(e.target.value.toLowerCase())))});\ndocument.addEventListener('keydown',e=>{const row=e.target.closest('tr[data-user]');if(row&&statusData.appConnected&&['Enter',' '].includes(e.key)){e.preventDefault();showLiveUser(row.dataset.user)}});\ndocument.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='applyDateRange'){userFrom=$('#rangeFrom').value;userTo=$('#rangeTo').value;if(!userFrom||!userTo||userFrom>userTo){usersError='Choose a start date on or before the end date.';render();return}usersLoaded=false;loadUsers()}if(b.id==='refreshUsers'){usersLoaded=false;loadUsers()}if(b.id==='publishLive')publishDialog();if(b.dataset.rollbackLive){const workflow=b.dataset.workflow,live=liveSettings.find(s=>s.workflow===workflow);modal('Restore this live configuration?','<p>This creates a new release from the selected historical settings. Existing patient notes remain unchanged.</p><p class=\"status error\" id=\"modalError\"></p><button id=\"confirmRollbackLive\" class=\"primary full\">Restore to live</button>');$('#confirmRollbackLive').onclick=()=>run(async()=>{await api('release',{workflow,releaseId:b.dataset.rollbackLive,expected:live?.revision||0});await refreshLive();await loadEvents();$('#modal').close();render();message('Earlier configuration restored as a new live release.')})}});\n\n\nconst betaRender=render;render=function(){betaRender();if(view==='users'&&statusData.appConnected){const b=document.createElement('button');b.className='primary';b.id='createBetaUser';b.textContent='Create beta user';document.querySelector('#refreshUsers').before(b)}};\ndocument.addEventListener('click',e=>{if(e.target.closest('#createBetaUser')){modal('Create beta user','<p>Create an approved email/password account without sending a confirmation email. Share the temporary password privately with the tester. They choose their own password on first sign-in.</p><form id=\"betaUserForm\"><label for=\"betaEmail\">Tester email</label><input id=\"betaEmail\" type=\"email\" autocomplete=\"off\" required maxlength=\"254\"><p id=\"modalError\" class=\"status error\"></p><button class=\"primary full\">Create beta account</button></form>')}});\ndocument.addEventListener('submit',async e=>{if(e.target.id!=='betaUserForm')return;e.preventDefault();const b=e.target.querySelector('button');b.disabled=true;try{const d=await api('create-beta',{email:$('#betaEmail').value.trim()});modal('Beta account ready','<p><strong>'+esc(d.user.email)+'</strong></p><label for=\"betaTemporaryPassword\">Temporary password \u00b7 shown once</label><input id=\"betaTemporaryPassword\" type=\"password\" readonly autocomplete=\"off\"><button id=\"showBetaPassword\" class=\"full\">Show temporary password</button><p class=\"help\">Share this directly with the tester. It is not stored in admin history. Closing this dialog removes it from this screen.</p><p>Sign in at <a href=\"https://roundsai-five.vercel.app/\" target=\"_blank\" rel=\"noopener\">RoundsAI</a>. Choose a personal password on first sign-in. Fictional cases only.</p>');$('#betaTemporaryPassword').value=d.temporaryPassword;d.temporaryPassword=null;$('#showBetaPassword').onclick=()=>{$('#betaTemporaryPassword').type=$('#betaTemporaryPassword').type==='password'?'text':'password';$('#showBetaPassword').textContent=$('#betaTemporaryPassword').type==='password'?'Show temporary password':'Hide temporary password'};usersLoaded=false;}catch(err){$('#modalError').textContent=err.message;b.disabled=false}});\n\n(async()=>{try{const [s,p,q,a]=await Promise.all([api('status'),api('profiles'),api('questions'),api('activity')]);statusData=s;profiles=p.profiles;guardrails=p.guardrails;questions=q.questions;events=a.events;$('#email').textContent=s.email;if(s.appConnected)await refreshLive();render()}catch(e){$('#main').innerHTML='<div class=\"card\"><h2>Workspace unavailable</h2><p class=\"status error\">'+esc(e.message)+'</p><button onclick=\"location.reload()\">Retry</button></div>'}})();\n\ndocument.addEventListener('change',async e=>{if(e.target.id!=='userAdminToggle')return;const toggle=e.target,enabled=toggle.checked;toggle.disabled=true;try{await api('admin-role',{userId:toggle.dataset.userId,enabled});const u=realUsers.find(u=>u.id===toggle.dataset.userId);if(u)u.is_admin=enabled;await loadEvents();message(enabled?'Admin access granted.':'Admin access removed.');render()}catch(err){toggle.checked=!enabled;const el=document.createElement('p');el.className='status error';el.textContent=err.message;toggle.closest('p').after(el)}finally{toggle.disabled=false}});\n</script></body></html>\n";
